Here is the commit message:
i2c: mediatek: Fix generic definitions for bus frequency

The max frequency of mediatek i2c controller driver is
I2C_MAX_HIGH_SPEED_MODE_FREQ, not I2C_MAX_FAST_MODE_PLUS_FREQ.
Fix it.

Fixes: 90224e6468e1 ("i2c: drivers: Use generic definitions for bus frequencies")
Reviewed-by: Yingjoe Chen <yingjoe.chen@mediatek.com>
Reviewed-by: Andy Shevchenko <andy.shevchenko@gmail.com>
Signed-off-by: Qii Wang <qii.wang@mediatek.com>
Signed-off-by: Wolfram Sang <wsa@kernel.org>

Here is the root cause:
The bug was caused by using an incorrect maximum frequency definition for the Mediatek I2C controller driver. The driver was capping the `target_speed` at `I2C_MAX_FAST_MODE_PLUS_FREQ`, which is lower than the actual maximum frequency supported by the controller, leading to potential communication issues when attempting to operate at higher speeds.

Here is the patch:
  */
 static int mtk_i2c_calculate_speed(struct mtk_i2c *i2c, unsigned int clk_src,
 				   unsigned int target_speed,
 				   unsigned int *timing_step_cnt,
 				   unsigned int *timing_sample_cnt)
 {
 	unsigned int step_cnt;
 	unsigned int sample_cnt;
 	unsigned int max_step_cnt;
 	unsigned int base_sample_cnt = MAX_SAMPLE_CNT_DIV;
 	unsigned int base_step_cnt;
 	unsigned int opt_div;
 	unsigned int best_mul;
 	unsigned int cnt_mul;
 	int ret = -EINVAL;

-	if (target_speed > I2C_MAX_FAST_MODE_PLUS_FREQ)
-		target_speed = I2C_MAX_FAST_MODE_PLUS_FREQ;
+	if (target_speed > I2C_MAX_HIGH_SPEED_MODE_FREQ)
+		target_speed = I2C_MAX_HIGH_SPEED_MODE_FREQ;

 	max_step_cnt = mtk_i2c_max_step_cnt(target_speed);
 	base_step_cnt = max_step_cnt;
 	/* Find the best combination */
 	opt_div = DIV_ROUND_UP(clk_src >> 1, target_speed);
 	best_mul = MAX_SAMPLE_CNT_DIV * max_step_cnt;

 	/* Search for the best pair (sample_cnt, step_cnt) with
 	 * 0 < sample_cnt < MAX_SAMPLE_CNT_DIV
 	 * 0 < step_cnt < max_step_cnt
 	 * sample_cnt * step_cnt >= opt_div
 	 * optimizing for sample_cnt * step_cnt being minimal
 	 */
 	for (sample_cnt = 1; sample_cnt <= MAX_SAMPLE_CNT_DIV; sample_cnt++) {
 		step_cnt = DIV_ROUND_UP(opt_div, sample_cnt);
 		cnt_mul = step_cnt * sample_cnt;
 		if (step_cnt > max_step_cnt)
 			continue;

 		if (cnt_mul < best_mul) {
 			ret = mtk_i2c_check_ac_timing(i2c, clk_src,
 				target_speed, step_cnt - 1, sample_cnt - 1);
 			if (ret)
 				continue;

 			best_mul = cnt_mul;
 			base_sample_cnt = sample_cnt;
 			base_step_cnt = step_cnt;
 			if (best_mul == opt_div)
 				break;
 		}
 	}

 	if (ret)
 		return -EINVAL;

 	sample_cnt = base_sample_cnt;
 	step_cnt = base_step_cnt;

 	if ((clk_src / (2 * sample_cnt * step_cnt)) > target_speed) {
 		/* In this case, hardware can't support such
 		 * low i2c_bus_freq
 		 */
 		dev_dbg(i2c->dev, "Unsupported speed (%uhz)\n",	target_speed);
 		return -EINVAL;
 	}

 	*timing_step_cnt = step_cnt - 1;
 	*timing_sample_cnt = sample_cnt - 1;

 	return 0;
 }



